@Repository
@RequiredArgsConstructor
class LogDiaRepository {

    private final JdbcTemplate jdbc;          // LOGS[n] y DESS[n] pasan a tablas particionadas por día contable
    private final ValidadorDf validador;      // DFVALIDA

    /** CARGAMEMORY: valida (función 1) y graba en LOG y DES del canal. */
    @Transactional
    void cargaMemoria(MovimientoIdf mov, Canal canal, boolean grabaMov) {
        if (mov.funcion() == 1) {
            validador.valida(mov);            // DFVALIDA(ALOG1, sistema, producto, GIND1)
        }
        if (grabaMov) {
            jdbc.update(INSERT_LOG, mov.logParams(canal));   // GRABALOG(LOGS[n], ALOG1, ..., DESS[n], ...)
            jdbc.update(INSERT_DES, mov.desParams(canal));
        }
        // DFAMPLIAFILE (20000 registros de 75 y 5000 de 90 cuando quedan menos de 5 libres)
        // no tiene equivalente: la tabla crece sola. Se deja una métrica de volumen por canal.
    }
}

    /** REBLOCKADE: 31 = bloque grande sin sincronizar (carga masiva); 32 = bloque chico con SYNCHRONIZE OUT. */
    void reblockade(Funcion f, Canal canal) {
        cargaMemoria(movPendiente, canal, grabaMov);          // CARGAMEMORY antes de cerrar
        modoEscritura.set(canal.numDia(), switch (f) {
            case BLOQUE_GRANDE -> ModoEscritura.LOTE;         // BLOCKSIZE 10800, SYNCHRONIZE NO
            case BLOQUE_NORMAL -> ModoEscritura.INMEDIATO;    // BLOCKSIZE 150/90, SYNCHRONIZE OUT
            default -> throw new IllegalStateException(f.name());
        });
    }

/**
 * LOTE: el repositorio acumula inserts y hace batchUpdate cada N registros (commit diferido).
 * INMEDIATO: cada movimiento se confirma al escribirse, equivalente a SYNCHRONIZE = OUT.
 */
enum ModoEscritura { LOTE, INMEDIATO }

@Service
@RequiredArgsConstructor
class CierreDiaService {

    private final ControlDiaClient l001;     // CONSISDIA en L001/CONTROL
    private final RegistrasProperties props;

    /** FINAL (función 98): cierra LOG, DES y SDO del canal y avisa a L001. */
    void cierre(Canal canal) {
        logDia.cierra(canal);                // CLOSE LOGS, DESS, SDOS ... LOCK
        int resultCtl = 1;
        for (int intento = 0; resultCtl > 0 && intento < 3; intento++) {
            resultCtl = l001.consisDia(new ControlE1(5, props.sistLib(), props.csiLib(), 0));
            // El fuente reintenta sin pausa; se agrega un backoff corto (configurable).
        }
        if (resultCtl > 0) {
            log.error("ERROR EN FUNCION 98 L002/REGISTRAS{} , RESULT L001/CONTROL {} "
                    + "NO SE MODIF. ESTATUS DE PROY. FECHA", props.sistLib(), resultCtl);
            // El fuente no aborta ni regresa error al llamador: RESULT sigue en 0.
        }
    }
}

@Component
@RequiredArgsConstructor
class ErroresRegistras {

    private final ErrorLogRepository errores;     // ERRORES1
    private final CommandPostClient cpost;        // L002COMMPOST / RSENDAUTO
    private final Map<Integer, AtomicLong> porResultado = new ConcurrentHashMap<>();   // NUM_ERROR[RESULT]

    void registra(int result, byte[] alog2, String texto, int tipo) {
        Fixed.putNibbles(alog2, 1078, 2, result); // POINTER(ALOG2,4)+1078: dígito 1078 = byte 539
        errores.append(Arrays.copyOf(alog2, 90)); // WRITE(ERRORES1[NIVERROR1], 90, ALOG2)

        long n = porResultado.computeIfAbsent(result, k -> new AtomicLong()).incrementAndGet();
        if (n == 1) {
            cpost.envia(texto, tipo);             // primer error de este tipo: aviso completo
        } else if (n % 100 == 0) {
            cpost.envia("LLEVO %08d, MENSAJES DE ERROR DEL TIPO DE RESULT = %02d".formatted(n, result), 2);
        }
    }
}
